        }
    }

    if let spaceID = app.spaceID, let url = URL(string: "https://huggingface.co/spaces/\(spaceID)") {
        Section {
            Link(destination: url) {
                Label(.reachy("View on Hugging Face"), systemImage: "arrow.up.forward.square")
            }
        }
    }
}
